install_info.claude_config:
{
  "mcpServers": {
    // ... other servers might be here ...
    "neuronwriter": {
      "type": "stdio",
      "command": "node",
      "args": [
        "C:/path/to/your/project/neuronwriter-mcp-server/build/index.js"
      ],
      "env": {
        "NEURONWRITER_API_KEY": "your-api-key-here"
      },
      "disabled": false,
      "alwaysAllow": [
        "list_projects",
        "get_query",
        "list_queries",
        "get_content",
        "import_content",
        "evaluate_content"
      ]
    }
  }
}
